import{_ as e,o as a,i as t,ad as s}from"./chunks/framework.Cq4hg8jX.js";const g=JSON.parse('{"title":"Agent Skills","description":"AI-assisted development skill for using and extending PikaCSS.","frontmatter":{"title":"Agent Skills","description":"AI-assisted development skill for using and extending PikaCSS.","relatedPackages":["@pikacss/core","@pikacss/unplugin-pikacss","@pikacss/plugin-icons","@pikacss/plugin-design-tokens"],"relatedSources":["skills/pikacss-use/SKILL.md",".claude-plugin/marketplace.json"],"category":"integrations","order":30},"headers":[],"relativePath":"integrations/agent-skills.md","filePath":"integrations/agent-skills.md"}'),n={name:"integrations/agent-skills.md"};function l(o,i,r,d,c,p){return a(),t("div",null,[...i[0]||(i[0]=[s(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /integrations/agent-skills.md for this page in Markdown format</div><h1 id="agent-skills" tabindex="-1">Agent Skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to “Agent Skills”">​</a></h1><p>PikaCSS ships with an agent skill that provides AI-assisted guidance for both consuming and extending PikaCSS. Install it as a Claude Code plugin, or with the <code>skills</code> CLI for any other supported coding agent.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to “Install”">​</a></h2><h3 id="claude-code-plugin" tabindex="-1">Claude Code Plugin <a class="header-anchor" href="#claude-code-plugin" aria-label="Permalink to “Claude Code Plugin”">​</a></h3><p>In Claude Code, add this repository as a plugin marketplace, then install the plugin:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/plugin marketplace add pikacss/pikacss</span></span>
<span class="line"><span>/plugin install pikacss@pikacss</span></span></code></pre></div><p>Claude loads the skill on its own when your work matches its description; see <a href="#how-to-trigger">How to Trigger</a> to invoke it explicitly. <code>/plugin marketplace update</code> refreshes the marketplace to the skill content on the repository&#39;s default branch, which can be ahead of the latest npm release.</p><h3 id="skills-cli" tabindex="-1">Skills CLI <a class="header-anchor" href="#skills-cli" aria-label="Permalink to “Skills CLI”">​</a></h3><p>For any supported agent, including Claude Code, install the skill directly with the <a href="https://www.npmjs.com/package/skills" target="_blank" rel="noreferrer"><code>skills</code> CLI</a>:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pikacss/pikacss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pikacss-use</span></span></code></pre></div><p>Both paths install the same <code>skills/pikacss-use</code> content.</p><h2 id="pikacss-use" tabindex="-1">pikacss-use <a class="header-anchor" href="#pikacss-use" aria-label="Permalink to “pikacss-use”">​</a></h2><h3 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to “When to Use”">​</a></h3><p>Use this skill when you are working with PikaCSS in any capacity:</p><ul><li>Setting up PikaCSS in a new project</li><li>Configuring engine options or build integrations</li><li>Using <code>pika()</code> and its variants</li><li>Consuming official plugins (reset, icons, fonts, typography, and design tokens)</li><li>Troubleshooting transforms, generated files, TypeScript declarations, or configuration reloads</li><li>Choosing neutral or Node.js runtime adapters for plugins that load local resources</li><li>Creating a new engine plugin from scratch</li><li>Implementing plugin hooks, structured diagnostics, and lifecycle behavior</li><li>Extending <code>EngineConfig</code> with module augmentation</li><li>Registering external configuration dependencies for file watching</li><li>Writing plugin tests</li></ul><h3 id="how-to-trigger" tabindex="-1">How to Trigger <a class="header-anchor" href="#how-to-trigger" aria-label="Permalink to “How to Trigger”">​</a></h3><p>The skill is automatically activated when your question relates to PikaCSS usage or plugin development. You can also explicitly mention &quot;using PikaCSS&quot;, &quot;PikaCSS setup&quot;, or &quot;PikaCSS plugin development&quot; in your prompt.</p><p>Installed as a Claude Code plugin, the skill is namespaced: invoke it with <code>/pikacss:pikacss-use</code>. Installed with the <code>skills</code> CLI, it is not namespaced and appears under its own name, <code>/pikacss-use</code>.</p><h3 id="coverage" tabindex="-1">Coverage <a class="header-anchor" href="#coverage" aria-label="Permalink to “Coverage”">​</a></h3><ul><li>Installation and build tool integration (Vite, Webpack, Rollup, esbuild, Rspack, Rolldown, and Nuxt)</li><li>Node.js, Vite, source-file, and static-analysis compatibility constraints</li><li>Engine configuration and customization</li><li>Generated CSS and TypeScript declaration files</li><li>The <code>pika()</code>, <code>pika.str()</code>, and <code>pika.arr()</code> functions</li><li>Official plugin consumption and configuration</li><li>Neutral and Node.js plugin entry points</li><li>ESLint integration</li><li>TypeScript autocomplete support</li><li>Plugin structure and <code>defineEnginePlugin</code></li><li>Lifecycle hooks, hook context, diagnostics, and execution order</li><li>Config augmentation via TypeScript module augmentation</li><li>Layer management and preflight injection</li><li>Selector, shortcut, variable, keyframe, and design-token registration</li><li>External config dependency watching</li><li>Plugin testing patterns using <code>createEngine</code></li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/getting-started/setup.html">Setup</a> — install PikaCSS in your project.</li><li><a href="/plugin-development/create-a-plugin.html">Plugin Development</a> — create your own plugins.</li></ul>`,23)])])}const u=e(n,[["render",l]]);export{g as __pageData,u as default};
